// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract C { uint8 public value = 3; int8 public signedValue = -2; function mutate(uint8 input) external returns (uint8) { uint8 prior = input++; ++input; value++; uint8 oldValue = value--; unchecked { --value; value++; signedValue = -signedValue; } signedValue = -signedValue; delete prior; delete value; return input + oldValue; } }
